import{_ as d,a,b as e,c as r,d as i,e as o}from"./chunks/arm_10pin_jtag_connector_pinout.5fpEPKOC.js";import{_ as l,o as h,c as s,al as n}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"mRo Pixhawk 비행 컨트롤러 (Pixhawk 1)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/mro_pixhawk.md","filePath":"ko/flight_controller/mro_pixhawk.md"}'),c={name:"ko/flight_controller/mro_pixhawk.md"};function p(b,t,u,m,k,f){return h(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="mro-pixhawk-비행-컨트롤러-pixhawk-1" tabindex="-1">mRo Pixhawk 비행 컨트롤러 (Pixhawk 1) <a class="header-anchor" href="#mro-pixhawk-비행-컨트롤러-pixhawk-1" aria-label="Permalink to &quot;mRo Pixhawk 비행 컨트롤러 (Pixhawk 1)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.mrobotics.io/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>mRo Pixhawk<sup>®</sup></em> is a hardware compatible version of the original <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The controller can be used as a drop-in replacement for the 3DR<sup>®</sup> <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. The main difference is that it is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design, which corrects a bug that limited the original Pixhawk 1 to 1MB of flash.</p></div><p><img src="'+d+'" alt="mRo Pixhawk Image"></p><p>Assembly/setup instructions for use with PX4 are provided here: <a href="./../assembly/quick_start_pixhawk">Pixhawk Wiring Quickstart</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This autopilot is <a href="./../flight_controller/autopilot_pixhawk_standard">supported</a> by the PX4 maintenance and test teams.</p></div><h2 id="주요-특징" tabindex="-1">주요 특징 <a class="header-anchor" href="#주요-특징" aria-label="Permalink to &quot;주요 특징&quot;">​</a></h2><ul><li><p>마이크로 프로세서:</p><ul><li>FPU가있는 32 비트 STM32F427 코어 텍스<sup>®</sup> M4 코어</li><li>168 MHz / 256 KB RAM / 2 MB 플래시</li><li>32 비트 STM32F100 failsafe 코프로세서</li><li>24 MHz/8 KB RAM/64 KB 플래시</li></ul></li><li><p>센서:</p><ul><li>ST Micro L3GD20 3축 16비트 자이로스코프</li><li>ST Micro LSM303D 3축 14비트 가속도계/자력계</li><li>Invensense<sup>®</sup> MPU 6000 3축 가속도계/자이로스코프</li><li>MEAS MS5611 기압계</li></ul></li><li><p>인터페이스:</p><ul><li>UART (직렬 포트) 5개, 1 개의 고전력 지원, 2x (HW 흐름 제어 포함)</li><li>CAN 2 개</li><li>최대 DX8의 Spektrum DSM/DSM2/DSM-X® Satellite 호환 입력(DX9 이상은 지원되지 않음)</li><li>Futaba<sup>®</sup> S.BUS 호환 입력 및 출력</li><li>PPM 합계 신호</li><li>RSSI(PWM 또는 전압) 입력</li><li>I2C</li><li>SPI</li><li>3.3 및 6.6V ADC 입력</li><li>외부 microUSB 포트</li></ul></li><li><p>전원시스템</p><ul><li>자동 복구 기능의 이상적인 다이오드 컨트롤러</li><li>서보 레일 고전력 (7V) 및 고전류 준비</li><li>모든 주변 장치 출력 과전류 보호, 모든 입력 ESD 보호</li></ul></li><li><p>중량과 크기</p><ul><li>무게 : 38g (1.31oz)</li><li>너비 : 50mm (1.96 &quot;)</li><li>두께 : 15.5mm (.613 &quot;)</li><li>길이 : 81.5mm (3.21&quot;)</li></ul></li></ul><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><ul><li><a href="https://store.mrobotics.io/Genuine-PixHawk-1-Barebones-p/mro-pixhawk1-bb-mr.htm" target="_blank" rel="noreferrer">Bare Bones</a> - Just the board (useful as a 3DR Pixhawk replacement)</li><li><a href="https://store.mrobotics.io/Genuine-PixHawk-Flight-Controller-p/mro-pixhawk1-minkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Essential Kit!</a> - Everything except for telemetry radios</li><li><a href="https://store.mrobotics.io/product-p/mro-pixhawk1-fullkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Cool Kit! (Limited edition)</a> - Everything you need including telemetry radios</li></ul><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v3_default</span></span></code></pre></div><h2 id="디버그-포트" tabindex="-1">디버그 포트 <a class="header-anchor" href="#디버그-포트" aria-label="Permalink to &quot;디버그 포트&quot;">​</a></h2><h3 id="콘솔-포트" tabindex="-1">콘솔 포트 <a class="header-anchor" href="#콘솔-포트" aria-label="Permalink to &quot;콘솔 포트&quot;">​</a></h3><p>The <a href="./../debug/system_console">PX4 System Console</a> runs on the port labeled <a href="#serial-4-5-port">SERIAL4/5</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A convenient way to connect to the console is to use a <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a>, as it comes with connectors that can be used with several different Pixhawk devices. Simply connect the 6-pos DF13 1:1 cable on the <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a> to the Pixhawk <code>SERIAL4/5</code> port.</p><p><img src="'+a+'" alt="Zubax BugFace BF1"></p></div><p>The pinout is standard serial pinout, designed to connect to a <a href="https://www.digikey.com/en/products/detail/TTL-232R-3V3/768-1015-ND/1836393" target="_blank" rel="noreferrer">3.3V FTDI</a> cable (5V tolerant).</p><table tabindex="0"><thead><tr><th>3DR Pixhawk 1</th><th></th><th>FTDI</th><th></th></tr></thead><tbody><tr><td>1</td><td>+5V (적)</td><td></td><td>N/C</td></tr><tr><td>2</td><td>S4 Tx</td><td></td><td>N/C</td></tr><tr><td>3</td><td>S4 Rx</td><td></td><td>N/C</td></tr><tr><td>4</td><td>S5 Tx</td><td>5</td><td>FTDI RX (황)</td></tr><tr><td>5</td><td>S5 Rx</td><td>4</td><td>FTDI TX (적황)</td></tr><tr><td>6</td><td>GND</td><td>1</td><td>FTDI GND (흑)</td></tr></tbody></table><p>The wiring for an FTDI cable to a 6-pos DF13 1:1 connector is shown in the figure below.</p><p><img src="'+e+'" alt="Console Connector"></p><p>The complete wiring is shown below.</p><p><img src="'+r+'" alt="Console Debug"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For information on how to <em>use</em> the console see: <a href="./../debug/system_console">System Console</a>.</p></div><h3 id="swd-포트" tabindex="-1">SWD 포트 <a class="header-anchor" href="#swd-포트" aria-label="Permalink to &quot;SWD 포트&quot;">​</a></h3><p>The <a href="./../debug/swd_debug">SWD</a> (JTAG) ports are hidden under the cover (which must be removed for hardware debugging). There are separate ports for FMU and IO, as highlighted below.</p><p><img src="'+i+'" alt="Pixhawk SWD"></p><p>The ports are ARM 10-pin JTAG connectors, which you will probably have to solder. The pinout for the ports is shown below (the square markers in the corners above indicates pin 1).</p><p><img src="'+o+'" alt="ARM 10-Pin connector pinout"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All Pixhawk FMUv2 boards have a similar SWD port.</p></div><h2 id="핀배열" tabindex="-1">핀배열 <a class="header-anchor" href="#핀배열" aria-label="Permalink to &quot;핀배열&quot;">​</a></h2><h4 id="telem1-telem2-포트" tabindex="-1">TELEM1, TELEM2 포트 <a class="header-anchor" href="#telem1-telem2-포트" aria-label="Permalink to &quot;TELEM1, TELEM2 포트&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>TX (출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>RX (입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>CTS (입력)</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>RTS (출력)</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="gps-포트" tabindex="-1">GPS 포트 <a class="header-anchor" href="#gps-포트" aria-label="Permalink to &quot;GPS 포트&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>TX (출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>RX (입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>CAN2 TX</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>CAN2 RX</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="serial-4-5-port" tabindex="-1">SERIAL 4/5 port <a class="header-anchor" href="#serial-4-5-port" aria-label="Permalink to &quot;SERIAL 4/5 port&quot;">​</a></h4><p>Due to space constraints two ports are on one connector.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>TX (#4)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>RX (#4)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>TX (#5)</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>RX (#5)</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-6-6v" tabindex="-1">ADC 6.6V <a class="header-anchor" href="#adc-6-6v" aria-label="Permalink to &quot;ADC 6.6V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>ADC 입력</td><td>최대 +6.6V</td></tr><tr><td>3 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-3-3v" tabindex="-1">ADC 3.3V <a class="header-anchor" href="#adc-3-3v" aria-label="Permalink to &quot;ADC 3.3V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>ADC 입력</td><td>최대 +3.3V</td></tr><tr><td>3 (흑)</td><td>GND</td><td>GND</td></tr><tr><td>4 (흑)</td><td>ADC 입력</td><td>최대 +3.3V</td></tr><tr><td>5 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="i2c" tabindex="-1">I2C <a class="header-anchor" href="#i2c" aria-label="Permalink to &quot;I2C&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>SCL</td><td>+3.3 (풀업)</td></tr><tr><td>3 (흑)</td><td>SDA</td><td>+3.3 (풀업)</td></tr><tr><td>4 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="can" tabindex="-1">CAN <a class="header-anchor" href="#can" aria-label="Permalink to &quot;CAN&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>CAN_H</td><td>+12V</td></tr><tr><td>3 (흑)</td><td>CAN_L</td><td>+12V</td></tr><tr><td>4 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="spi" tabindex="-1">SPI <a class="header-anchor" href="#spi" aria-label="Permalink to &quot;SPI&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>SPI_EXT_SCK</td><td>+3.3</td></tr><tr><td>3 (흑)</td><td>SPI_EXT_MISO</td><td>+3.3</td></tr><tr><td>4 (흑)</td><td>SPI_EXT_MOSI</td><td>+3.3</td></tr><tr><td>5 (흑)</td><td>!SPI_EXT_NSS</td><td>+3.3</td></tr><tr><td>6 (흑)</td><td>!GPIO_EXT</td><td>+3.3</td></tr><tr><td>7 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="전원" tabindex="-1">전원 <a class="header-anchor" href="#전원" aria-label="Permalink to &quot;전원&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>VCC</td><td>+5V</td></tr><tr><td>3 (흑)</td><td>CURRENT</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>VOLTAGE</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>GND</td><td>GND</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="스위치" tabindex="-1">스위치 <a class="header-anchor" href="#스위치" aria-label="Permalink to &quot;스위치&quot;">​</a></h4><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+3.3V</td></tr><tr><td>2 (흑)</td><td>!IO_LED_SAFETY</td><td>GND</td></tr><tr><td>3 (흑)</td><td>SAFETY</td><td>GND</td></tr></tbody></table><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO 디버그</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (흐름 제어)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (흐름 제어)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>콘솔</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="시리얼-포트-매핑-1" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑-1" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO 디버그</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (흐름 제어)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (흐름 제어)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>콘솔</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="회로도" tabindex="-1">회로도 <a class="header-anchor" href="#회로도" aria-label="Permalink to &quot;회로도&quot;">​</a></h2><p>The board is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design.</p><ul><li><a href="https://github.com/pixhawk/Hardware/raw/master/FMUv3_REV_D/Schematic%20Print/Schematic%20Prints.PDF" target="_blank" rel="noreferrer">FMUv3 schematic</a> -- Schematic and layout</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>As a CC-BY-SA 3.0 licensed Open Hardware design, all schematics and design files are <a href="https://github.com/pixhawk/Hardware" target="_blank" rel="noreferrer">available</a>.</p></div>',62)])])}const w=l(c,[["render",p]]);export{g as __pageData,w as default};
